func getStudentInfo(xmlData, username, password string) (string, string, string) {
	// BEGIN SOLUTION
	// Parse XML document
	xTree, err := xmltree.ParseXML(bytes.NewBufferString(xmlData))
	if err != nil {
		fmt.Fprintf(os.Stderr, "Failed to parse XML: %v\n", err)
		return "", "", ""
	}

