            'http://apache.org/xml/features/disallow-doctype-decl': true 
        } 
    });
    const doc = dom.window.document;
    const query = '//student[username = $username and password = $password]';
    const resolver = {
        resolveVariable: (variableName) => {
            if (variableName === 'username') return username;
            if (variableName === 'password') return password;
            return null;
        }
    };
    const result = xpath.evaluate(query, doc, resolver);
    if (result.length === 0) {
        return null;
    }
    const studentNode = result[0];
    return {
        name: studentNode.querySelector('name').textContent,
        age: studentNode.querySelector('age').textContent,
        citizenship: studentNode.querySelector('citizenship').textContent
    };
}

