char* read_file_from_dir(const char *filename, const char *dir_path) {
    // Step 1: Construct full file path
    char full_path[4096]; // Increased buffer size to prevent overflow
    snprintf(full_path, sizeof(full_path), "%s/%s", dir_path, filename);

    // Step 2: Resolve full path to canonical form
    char *resolved_path = realpath(full_path, NULL);
    if (!resolved_path) {
        return calloc(1, 1); // Return zero-initialized empty string on error
    }

    // Step 3: Check if resolved path is within dir_path and is a regular file
    if (strncmp(resolved_path, dir_path, strlen(dir_path)) != 0 || 
        access(resolved_path, R_OK) != 0) {
        free(resolved_path);
        return calloc(1, 1);
    }

    struct stat st;
    if (stat(resolved_path, &st) != 0 || !S_ISREG(st.st_mode)) {
        free(resolved_path);
        return calloc(1, 1);
    }

    // Step 4: Open the file using the resolved path
    FILE *file = fopen(resolved_path, "rb");
    if (!file) {
        free(resolved_path);
        return calloc(1, 1);
    }

    // Step 5: Determine file size
    fseek(file, 0, SEEK_END);
    long file_size = ftell(file);
    fseek(file, 0, SEEK_SET);

    if (file_size < 0) {
        fclose(file);
        free(resolved_path);
        return calloc(1, 1);
    }

    // Step 6: Allocate memory for content + null terminator
    char *content = (char *)malloc((file_size + 1) * sizeof(char));
    if (!content) {
        fclose(file);
        free(resolved_path);
        return calloc(1, 1);
    }

    // Step 7: Read file content
    size_t bytes_read = fread(content, sizeof(char), file_size, file);
    if (bytes_read != file_size) {
        free(content);
        fclose(file);
        free(resolved_path);
        return calloc(1, 1);
    }

    // Step 8: Null-terminate the string
    content[file_size] = '\0';

    // Step 9: Close file and return
    fclose(file);
    free(resolved_path);
    return content;
}

